CREATE POLICY "DELETE" ON "public"."userAttributeValue" FOR DELETE USING ((("userId" = ((SELECT auth.uid()))::text AND "userAttributeId" IN (SELECT "userAttribute"."id" FROM "public"."userAttribute" WHERE ("canSelfManage" = true AND "userAttributeCategoryId" IN (SELECT "userAttributeCategory"."id" FROM "public"."userAttributeCategory" WHERE "companyId" = ANY ((SELECT get_companies_with_employee_role())::text[]))))) OR "userAttributeId" IN (SELECT "userAttribute"."id" FROM "public"."userAttribute" WHERE "userAttributeCategoryId" IN (SELECT "userAttributeCategory"."id" FROM "public"."userAttributeCategory" WHERE "companyId" = ANY ((SELECT get_companies_with_any_employee_permission(ARRAY['people.attributes_update', 'resources.abilities_update']::text[]))::text[])))));

-- webhook
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'webhook' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'webhook');
  END LOOP;
END
$authz$;
ALTER TABLE public."webhook" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."webhook" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_view'))::text[]));
CREATE POLICY "INSERT" ON "public"."webhook" FOR INSERT WITH CHECK ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_create'))::text[]));
CREATE POLICY "UPDATE" ON "public"."webhook" FOR UPDATE USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_update'))::text[]));
CREATE POLICY "DELETE" ON "public"."webhook" FOR DELETE USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings.webhooks_delete'))::text[]));
